        message.set_method(coap::Method::POST);
        message.set_payload(payload.to_vec());
        message.set_token(b"1234".to_vec());
        message.set_content_format(coap::ContentFormat::ApplicationJson);
        message.set_max_age(Duration::from_secs(60));
        message.set_uri_path(b"sensor/data");

